  `QRCode` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'QR code data for ticket scanning',
  `TicketPDF` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Path to generated PDF ticket',
