INSERT INTO `email_template` VALUES (1,'REGISTRATION_EMAIL','Welcome Registration Email','Chào mừng đến với Cinema System!','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <style>\r\n        body {\r\n            font-family: Arial, sans-serif;\r\n            line-height: 1.6;\r\n            color: #333;\r\n            max-width: 600px;\r\n            margin: 0 auto;\r\n            padding: 20px;\r\n        }\r\n        .container {\r\n            background-color: #f9f9f9;\r\n            border-radius: 10px;\r\n            padding: 30px;\r\n            box-shadow: 0 2px 5px rgba(0,0,0,0.1);\r\n        }\r\n        .header {\r\n            background-color: #4CAF50;\r\n            color: white;\r\n            padding: 20px;\r\n            text-align: center;\r\n            border-radius: 10px 10px 0 0;\r\n            margin: -30px -30px 20px -30px;\r\n        }\r\n        .content {\r\n            background-color: white;\r\n            padding: 20px;\r\n            border-radius: 5px;\r\n        }\r\n        .footer {\r\n            margin-top: 20px;\r\n            text-align: center;\r\n            font-size: 12px;\r\n            color: #777;\r\n        }\r\n        .info-box {\r\n            background-color: #e8f5e9;\r\n            border-left: 4px solid #4CAF50;\r\n            padding: 15px;\r\n            margin: 15px 0;\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"container\">\r\n        <div class=\"header\">\r\n            <h1>Chào mừng!</h1>\r\n        </div>\r\n        <div class=\"content\">\r\n            <h2>Xin chào {FullName}!</h2>\r\n            <p>Cảm ơn bạn đã đăng ký tài khoản với hệ thống của chúng tôi. Chúng tôi rất vui mừng được chào đón bạn!</p>\r\n            \r\n            <div class=\"info-box\">\r\n                <strong>Thông tin tài khoản của bạn:</strong><br>\r\n                Tên đăng nhập: <strong>{UserName}</strong><br>\r\n                Email: <strong>{Email}</strong>\r\n            </div>\r\n            \r\n            <p>Bạn có thể đăng nhập vào tài khoản của mình và bắt đầu sử dụng các dịch vụ của chúng tôi.</p>\r\n            \r\n            <p>Nếu bạn có bất kỳ câu hỏi nào hoặc cần hỗ trợ, vui lòng liên hệ với đội ngũ hỗ trợ của chúng tôi.</p>\r\n            \r\n            <p>Trân trọng,<br>\r\n            <strong>Đội ngũ Cinema System</strong></p>\r\n        </div>\r\n        <div class=\"footer\">\r\n            <p>Đây là email tự động. Vui lòng không trả lời tin nhắn này.</p>\r\n            <p>&copy; 2025 Cinema System. Bản quyền thuộc về chúng tôi.</p>\r\n        </div>\r\n    </div>\r\n</body>\r\n</html>','Email template for new user registration',1,'2025-11-02 18:45:50','System',NULL,NULL);
/*!40000 ALTER TABLE `email_template` ENABLE KEYS */;
UNLOCK TABLES;

