INSERT INTO `movie` VALUES (17,'Mùi Phở','mi-ph','Câu chuyện về sự xung đột thế hệ và những va chạm giữa quan niệm cũ và lối sống hiện đại, xoay quanh món Phở - biểu tượng ẩm thực Việt. Đằng sau những mâu thuẫn và tranh cãi ấy, từng bí mật dần được hé lộ, mở ra hành trình tìm lại sự ấm áp của tình thân qua những tình tiết hài hước, dí dỏm và đầy duyên dáng.',104,'2026-02-17','https://cdn-images.vtv.vn/thumb_w/1200/66349b6076cb4dee98746cf1/2025/11/21/mui-pho-7-46516021173887635499014.jpg','https://www.youtube.com/watch?v=PfLNuXyLA4Q','Bùi Quang Minh','Nghệ sỹ Xuân Hinh - Diễn viên Thu Trang - Nghệ sỹ Thanh Thanh Hiền - Nghệ sỹ Quốc Tuấn - Bảo Nam - Hà Hương - Thanh Hương - Chu Mạnh Cường - Tiến Lộc','Vietnamese','G','ComingSoon',0.00,'2025-12-20 14:14:23',NULL,'2025-12-20 19:40:03',NULL),(18,'Avatar: Lửa Và Tro Tàn','avatar-la-v-tro-tn','Sau nỗi đau khi mất đi đứa con trưởng, gia đình Jake Sully và Neytiri tiếp tục bị cuốn vào biến cố mới khi kẻ thù không đội trời chung Quaritch bắt tay với Varang - thủ lĩnh tộc Tro. Lần đầu trong suốt nhiều năm, đạo diễn James Cameron hé lộ mặt tối của người Na’vi, mang đến những góc khuất của Pandora mà khán giả chưa từng thấy trong Avatar: Lửa Và Tro Tàn.',197,'2025-12-19','https://upload.wikimedia.org/wikipedia/vi/5/58/Avatar_3_teaser.jpg','https://www.youtube.com/watch?v=erhF0RAnYvo&t=7s','James Cameron','Giovanni Ribisi, Kate Winslet, Zoe Saldaña.','Vietnamese','PG-13','NowShowing',0.00,'2025-12-20 16:55:06',NULL,'2025-12-20 19:42:46',NULL),(19,'Hoàng Tử Quỷ','hong-t-qu','Hoàng Tử Quỷ xoay quanh Thân Đức - một hoàng tử được sinh ra nhờ tà thuật. Trốn thoát khỏi cung cấm, Thân Đức tham vọng giải thoát Quỷ Xương Cuồng khỏi Ải Mắt Người để khôi phục Xương Cuồng Giáo. Nhưng kế hoạch của Thân Đức chỉ thành hiện thực khi hắn có đủ cả hai “nguyên liệu” - Du Hồn Giả và Bạch Hổ Nguyên Âm. Đội lốt một lang y hiền lành, muốn chữa bệnh cứu người, Thân Đức lên đường đến làng Hủi và đụng độ trưởng làng Lỗ Đạt mạnh mẽ, liệu hắn có thể đạt được âm mưu tà ác của mình?',117,'2025-12-05','https://upload.wikimedia.org/wikipedia/vi/f/ff/Hoang_tu_quy.jpg','https://www.youtube.com/watch?v=8sN-kdDxPSM','Trần Hữu Tấn','Anh Tú Atus, Lương Thế Thành, Hoàng Linh Chi, Huỳnh Thanh Trực, Rima Thanh Vy, Lê Hà Phương, Duy Luân,...','Vietnamese','NC-17','NowShowing',0.00,'2025-12-20 16:56:37',NULL,'2025-12-20 19:42:34',NULL),(20,'Phi Vụ Động Trời 2','phi-v-ng-tri-2','ZOOTOPIA 2 trở lại sau 9 năm Đu OTP Nick & Judy chuẩn bị 28.11.2025 này ra rạp nhé',107,'2025-11-28','https://upload.wikimedia.org/wikipedia/vi/5/52/Zootopia2.jpg','https://www.youtube.com/watch?v=c6qXf2Zg8K8','Jared Bush, Byron Howard','Jason Bateman, Quinta Brunson, Fortune Feimster','Vietnamese','G','NowShowing',0.00,'2025-12-20 16:58:15',NULL,'2025-12-20 19:42:27',NULL),(21,'Ai Thương Ai Mến','ai-thng-ai-mn','Lấy bối cảnh miền Tây sông nước, Ai Thương Ai Mến xoay quanh Hai Mến — người phụ nữ mất cha mẹ, một mình gồng gánh gia đình giữa nợ nần và những bi kịch dồn dập. Trong hành trình ấy, cô gặp cậu Khả (Ngọc Thuận) – công tử ăn chơi vô tình đem lòng thương mến, tạo nên mối tình vừa ngọt ngào vừa đau đớn. Song song đó, chuyện tình thơm lành của đôi trẻ Chờ – Thương trở thành điểm sáng trước khi cả ba tuyến nhân vật bước vào những thử thách chạm đến trái tim khán giả.',120,'2026-01-01','https://vimages.coccoc.com/vimage?ns=cinema&url=https%3A%2F%2Figuov8nhvyobj.vcdn.cloud%2Fmedia%2Fcatalog%2Fproduct%2Fcache%2F1%2Fimage%2Fc5f0a1eff4c394a251036189ccddaacd%2Fa%2Ft%2Fatam-payoff-0.7x1.jpg','https://www.youtube.com/watch?v=EAscg3He7Uk','Thu Trang','Ngọc Thuận, Thu Trang, Trâm Anh, Võ Điền Gia Huy, Khả Như, La Thành, Trương Minh Thảo, Tiến Luật và một số diễn viên khác','Vietnamese','R','ComingSoon',0.00,'2025-12-20 16:59:39',NULL,'2025-12-20 19:43:48',NULL),(22,'Thế Hệ Kỳ Tích (Bà Đừng Buồn Con)','th-h-k-tch-b-ng-bun-con','Chàng sinh viên Tiến (Trần Tú) mang trong mình giấc mơ tạo ra tựa game vươn tầm thế giới, dù liên tục bị xem thường và vấp ngã trên hành trình khởi nghiệp. Cùng với “thế hệ kỳ tích” – những người trẻ dám mơ và dám làm, Tiến từng bước khẳng định giá trị của bản thân. Giữa bao thử thách, tình yêu và niềm tin của người bà (NSND Thanh Hoa) chính là ngọn lửa giúp anh đứng dậy, biến ước mơ thành kỳ tích.',124,'2025-12-12','https://vimages.coccoc.com/vimage?ns=cinema&url=https%3A%2F%2Figuov8nhvyobj.vcdn.cloud%2Fmedia%2Fcatalog%2Fproduct%2Fcache%2F1%2Fimage%2Fc5f0a1eff4c394a251036189ccddaacd%2Fm%2Fa%2Fmain_thkt_cinema.jpg','https://www.youtube.com/watch?v=09g3UYPsgNs','Hoàng Nam','Trần Tú, NSND Thanh Hoa, NSND Trần Lực, NSND Bùi Bài Bình, NSƯT Chiều Xuân, Quách Thu Phương, Hà Hương, Hiếu PC, Tuấn Hưng, Nàng Mơ và một số diễn viên khác','Vietnamese','G','NowShowing',0.00,'2025-12-20 17:01:42',NULL,'2025-12-20 19:44:38',NULL),(23,'Nhà Hai Chủ','nh-hai-ch','Một gia đình nhỏ vì không đủ điều kiện đã phải mua một căn nhà mà người dân xung quanh đồn đoán rằng có nhiều điều kỳ lạ tâm linh liệu gia đình sẽ đối mặt với ngôi nhà nhiều chủ sẽ như thế nào?',102,'2025-12-26','https://cdn.moveek.com/storage/media/cache/tall/6930f96081405436880285.jpg','https://www.youtube.com/watch?v=DBJcGuXXVOE','Trần Duy Linh & Phạm Trung Hiếu','Trâm Anh, Kim Hải, Tạ Lâm, Kim Phương ,Mộc Trà,…','Vietnamese','PG-13','ComingSoon',0.00,'2025-12-20 17:02:59',NULL,'2025-12-20 19:45:22',NULL),(24,'Biệt Đội Yoyo: Giải Cứu Giáng Sinh','bit-i-yoyo-giai-cu-giang-sinh','Ngay ngày đầu đi làm, Yoyo bàng hoàng nhận ra Bắc Cực không còn ánh sáng phép màu, mà bị thay thế bởi robot vô cảm và những dây chuyền lạnh lẽo. Khi một hacker bí ẩn chiếm quyền điều khiển xưởng quà, toàn bộ Giáng Sinh đứng trước nguy cơ bị xóa sổ, và Yoyo trở thành hy vọng cuối cùng. Cùng biệt đội của mình, cậu lao vào hành trình tìm lại ông già Noel, vượt qua bão tuyết, những cuộc đua kỳ lạ cũng như phải đối mặt với quá khứ đau lòng. Từ nhà xưởng hiện đại đến rừng băng kỳ ảo, mỗi bước đi là một thử thách, mỗi sai lầm là một bài học. Và chính trong hành trình ấy, Yoyo khám phá ra rằng phép màu thật sự luôn bắt đầu từ chính niềm tin bên trong mỗi con người.',96,'2025-12-24','https://images.fandango.com/ImageRenderer/820/0/redesign/static/img/default_poster.png/0/images/masterrepository/fandango/243713/missionsanta.jpg','https://www.youtube.com/watch?v=rtSnEo-xmRU','Damjan Mitrevski','Julius Weckauf, Oliver Kalkofe, Bettina Zimmermann, Michael Mendl','Vietnamese','PG','ComingSoon',0.00,'2025-12-20 17:04:32',NULL,'2025-12-20 17:44:11',NULL),(25,'Đụng Độ Siêu Trăn','ng-siu-trn','Doug (Jack Black) và Griff (Paul Rudd) là đôi bạn thân từ nhỏ, họ đã luôn mơ ước được làm lại bộ phim yêu thích nhất của mình là bộ phim kinh điển Anaconda. Khi khủng hoảng tuổi trung niên thúc đẩy họ đã liều lĩnh thực hiện. Cả bọn lên đường tiến sâu vào rừng Amazon để bắt đầu quay phim. Nhưng mọi chuyện trở nên nguy hiểm khi một con trăn khổng lồ thực sự xuất hiện, biến phim trường hỗn loạn hài hước của họ thành một tình huống chết người. Bộ phim mà họ khao khát làm “gần chết” có lẽ sẽ khiến họ mất mạng thật…',99,'2025-12-25','https://cinestar.com.vn/_next/image/?url=https%3A%2F%2Fapi-website.cinestar.com.vn%2Fmedia%2Fwysiwyg%2FPosters%2F12-2025%2FAnaconda.jpg&w=1920&q=75','https://www.youtube.com/watch?v=AS48X4DqoWc','Tom Gormican','Jack Black, Paul Rudd, Steve Zahn, Thandiwe Newton, Daniela Melchior, Selton Mello','Vietnamese','PG-13','ComingSoon',0.00,'2025-12-20 17:05:42',NULL,'2025-12-20 19:46:37',NULL),(26,'Spongebob: Lời Nguyền Hải Tặc','spongebob-li-nguyn-hi-tc','SpongeBob phiêu lưu xuống đáy đại dương để đối mặt với hồn ma của Người Hà Lan bay, vượt qua thử thách và khám phá những bí ẩn dưới biển.',96,'2025-12-26','https://cdn.cinenjoy.com/cinematimes/posters/6893b0b713427.jpg','https://www.youtube.com/watch?v=lHCH6N6d20g','Derek Drymon','Tom Kenny, Clancy Brown, Rodger Bumpass, Bill Fagerbakke, Carolyn Lawrence, Mr. Lawrence, George Lopez, Isis “Ice Spice” Gaston, Arturo Castro, Sherry Cola with Regina Hall and Mark Hamill','Vietnamese','G','ComingSoon',0.00,'2025-12-20 17:06:48',NULL,'2025-12-20 17:48:13',NULL),(28,'Vua Của Các Vua','vua-ca-cc-vua','The King of Kings là phim hoạt hình Hàn Quốc kể về cuộc đời Chúa Giê-su. Bộ phim đã tạo nên kỷ lục doanh thu toàn cầu, được khán giả Bắc Mỹ yêu thích với điểm số gần như tuyệt đối. Tác phẩm nổi bật bởi hình ảnh tinh xảo và thông điệp về tình yêu, phép màu và lòng biết ơn. Tại Việt Nam, phim sẽ ra mắt toàn quốc vào mùa Giáng Sinh, từ 12/12/2025.',101,'2025-12-12','https://www.themoviedb.org/t/p/w1280/wN2H9xHhSXyI58B5tg1K6T0wWc0.jpg','https://www.youtube.com/watch?v=wDT6jlmLimI','Seong-ho Jang','NSƯT Thành Lộc, Bạch Long, Huyền Chi, Hứa Vĩ Văn,...','Vietnamese','G','NowShowing',0.00,'2025-12-20 17:11:15',NULL,'2025-12-20 19:47:34',NULL);
/*!40000 ALTER TABLE `movie` ENABLE KEYS */;
